namespace ombra::search::detail {

using namespace lbcrypto;

namespace {

SecurityLevel security_level(const std::string& s) {
  if (s == "HEStd_128_classic") return HEStd_128_classic;
  if (s == "HEStd_192_classic") return HEStd_192_classic;
  if (s == "HEStd_256_classic") return HEStd_256_classic;
  if (s == "HEStd_128_quantum") return HEStd_128_quantum;
  if (s == "HEStd_192_quantum") return HEStd_192_quantum;
  if (s == "HEStd_256_quantum") return HEStd_256_quantum;
  throw std::runtime_error("preset: security level below 128 bits or unknown");  // never NotSet
}

ScalingTechnique scaling(const std::string& s) {
  if (s == "FIXEDMANUAL") return FIXEDMANUAL;
  if (s == "FIXEDAUTO") return FIXEDAUTO;
  if (s == "FLEXIBLEAUTO") return FLEXIBLEAUTO;
  if (s == "FLEXIBLEAUTOEXT") return FLEXIBLEAUTOEXT;
  throw std::runtime_error("preset: unknown scaling technique");
}

KeySwitchTechnique key_switch(const std::string& s) {
  if (s == "BV") return BV;
  if (s == "HYBRID") return HYBRID;
  throw std::runtime_error("preset: unknown key switch technique");
}

CryptoContext<DCRTPoly> build_context(const PresetParams& p) {
  CCParams<CryptoContextCKKSRNS> params;
  // The same calls, in the same order, as make_ckks_params and make_context in
  // client/ombra/params.py.
  params.SetSecurityLevel(security_level(p.security_level));
  params.SetRingDim(p.ring_dim);
  params.SetMultiplicativeDepth(p.depth);
  params.SetScalingModSize(p.scale_bits);
  params.SetFirstModSize(p.first_bits);
  params.SetBatchSize(p.batch);
  params.SetScalingTechnique(scaling(p.scaling_technique));
  params.SetKeySwitchTechnique(key_switch(p.key_switch_technique));
  params.SetCKKSDataType(CKKSDataType::REAL);
  params.SetDecryptionNoiseMode(DecryptionNoiseMode::FIXED_NOISE_DECRYPT);
  params.SetExecutionMode(ExecutionMode::EXEC_EVALUATION);
  if (p.num_large_digits != 0) params.SetNumLargeDigits(p.num_large_digits);
  auto cc = GenCryptoContext(params);
  cc->Enable(PKE);
  cc->Enable(KEYSWITCH);
  cc->Enable(LEVELEDSHE);
  return cc;
}

std::vector<std::uint8_t> serialize(const CryptoContext<DCRTPoly>& cc) {
  std::ostringstream out(std::ios::out | std::ios::binary);
  Serial::Serialize(cc, out, SerType::BINARY);
  const std::string s = out.str();
  return std::vector<std::uint8_t>(s.begin(), s.end());
}

struct Canonical {
  std::vector<std::uint8_t> bytes;         // as the C++ writer of this server serializes it
  std::vector<std::uint8_t> client_bytes;  // as the Python client serializes it
  std::size_t key_bytes = 0;  // lower bound of the size of one EvalKey: the coefficients only
  std::size_t max_keys = 0;   // most automorphism keys a client uploads: log2(N)
};

const Canonical* canonical(const std::string& preset) {
  static std::mutex mu;
  static std::map<std::string, std::unique_ptr<Canonical>> cache;
  const PresetParams* p = find_preset_params(preset);
  if (!p) return nullptr;
  std::lock_guard g(mu);
  auto& slot = cache[preset];
  if (!slot) {
    auto cc = build_context(*p);
    auto c = std::make_unique<Canonical>();
    c->bytes = serialize(cc);
    c->client_bytes.assign(p->client_context, p->client_context + p->client_context_size);
    const auto rns = std::dynamic_pointer_cast<CryptoParametersRNS>(cc->GetCryptoParameters());
    if (!rns) throw std::runtime_error("preset context is not an RNS scheme");
    // One hybrid key switching key: two vectors (a and b) of numPartQ polynomials over the
    // Q and P towers, 8 bytes per coefficient.
    const std::size_t towers = rns->GetParamsQP()->GetParams().size();
    c->key_bytes = std::size_t{2} * rns->GetNumPartQ() * towers * cc->GetRingDimension() * 8;
    for (std::size_t n = cc->GetRingDimension(); n > 1; n >>= 1) ++c->max_keys;
    slot = std::move(c);
  }
  return slot.get();
}

}  // namespace

std::vector<std::uint8_t> build_context_bytes(const PresetParams& p) {
  return serialize(build_context(p));
}

const PresetParams* find_preset_params(const std::string& preset) {
  for (const auto& p : generated::kPresetParams)
    if (preset == p.name) return &p;
  return nullptr;
}

const std::vector<std::uint8_t>* canonical_context(const std::string& preset) {
  const Canonical* c = canonical(preset);
  return c ? &c->bytes : nullptr;
}

const std::vector<std::uint8_t>* canonical_client_context(const std::string& preset) {
  const Canonical* c = canonical(preset);
  return c ? &c->client_bytes : nullptr;
}

void require_canonical_context(const std::string& preset,
                               const std::vector<std::uint8_t>& payload) {
  const Canonical* c = canonical(preset);
  if (!c) throw InvalidQuery("the collection's preset has no context on this server");
  if (payload != c->bytes && payload != c->client_bytes)
    throw InvalidQuery("the uploaded crypto context is not the context of the collection's preset");
}

void require_key_size(const std::string& preset, KeyKind kind, std::size_t size) {
  const Canonical* c = canonical(preset);
  if (!c) throw InvalidQuery("the collection's preset has no context on this server");
  // Per key: the coefficients plus under a kilobyte of tower moduli and type tags (measured 0.8 to
  // 1 KiB for both presets); about 1 KiB of header per file. The slack is generous but far below
  // the size of one key, so the number of keys is unique.
  constexpr std::size_t kSlack = 4096;
  const std::size_t hi_n = kind == KeyKind::EvalMult ? 1 : c->max_keys;
  for (std::size_t n = 1; n <= hi_n; ++n) {
    const std::size_t lo = n * c->key_bytes;
    const std::size_t hi = n * (c->key_bytes + kSlack) + kSlack;
    if (size >= lo && size <= hi) return;
  }
  throw InvalidQuery(kind == KeyKind::EvalMult
                         ? "the EvalMult key file has a size no key of the collection's preset has"
                         : "the automorphism key file has a size no key set of the collection's "
                           "preset has");
}

}  // namespace ombra::search::detail
